1,55186,'video_chatgpt_response',''),(23122,55186,'_video_chatgpt_response','field_67221dc82655d'),(23123,55186,'video_chatgpt_response_text',''),(23124,55186,'_video_chatgpt_response_text','field_6722334bac798'),(23125,55186,'video_transcript_json','[\r\n    {\r\n        \"text\": \"the catly or arm jump to climb up is\",\r\n        \"start\": 6,\r\n        \"duration\": 8.639\r\n    },\r\n    {\r\n        \"text\": \"arguably one of the most common parkour\",\r\n        \"start\": 11.24,\r\n        \"duration\": 6.68\r\n    },\r\n    {\r\n        \"text\": \"combinations that we do um sort of\",\r\n        \"start\": 14.639,\r\n        \"duration\": 5.64\r\n    },\r\n    {\r\n        \"text\": \"getting onto the side of a wall just to\",\r\n        \"start\": 17.92,\r\n        \"duration\": 4.279\r\n    },\r\n    {\r\n        \"text\": \"get onto the side you know sometimes\",\r\n        \"start\": 20.279,\r\n        \"duration\": 3.481\r\n    },\r\n    {\r\n        \"text\": \"that happens because you know you\'re\",\r\n        \"start\": 22.199,\r\n        \"duration\": 4.801\r\n    },\r\n    {\r\n        \"text\": \"going to perhaps a window sill um or a\",\r\n        \"start\": 23.76,\r\n        \"duration\": 5.04\r\n    },\r\n    {\r\n        \"text\": \"window ledge and you know you\'re not\",\r\n        \"start\": 27,\r\n        \"duration\": 3.279\r\n    },\r\n    {\r\n        \"text\": \"going to climb up there\'s no space to\",\r\n        \"start\": 28.8,\r\n        \"duration\": 4.32\r\n    },\r\n    {\r\n        \"text\": \"climb up but a lot of the time you will\",\r\n        \"start\": 30.279,\r\n        \"duration\": 5.681\r\n    },\r\n    {\r\n        \"text\": \"be climbing up on top of the wall after\",\r\n        \"start\": 33.12,\r\n        \"duration\": 5.92\r\n    },\r\n    {\r\n        \"text\": \"you\'ve done the arm jump so the\",\r\n        \"start\": 35.96,\r\n        \"duration\": 5.96\r\n    },\r\n    {\r\n        \"text\": \"combinati