9,55514,'video_youtube_data_description_filtered',''),(61920,55514,'_video_youtube_data_description_filtered','field_672253e91cdc8'),(61921,55514,'video_chatgpt_response',''),(61922,55514,'_video_chatgpt_response','field_67221dc82655d'),(61923,55514,'video_chatgpt_response_text',''),(61924,55514,'_video_chatgpt_response_text','field_6722334bac798'),(61925,55514,'video_transcript_json','[\r\n    {\r\n        \"text\": \"the next stage of learning how to do the\",\r\n        \"start\": 5.52,\r\n        \"duration\": 5.96\r\n    },\r\n    {\r\n        \"text\": \"dash vault is trying to jump onto the\",\r\n        \"start\": 7.64,\r\n        \"duration\": 6.879\r\n    },\r\n    {\r\n        \"text\": \"wall with your feet first so doing a box\",\r\n        \"start\": 11.48,\r\n        \"duration\": 6.48\r\n    },\r\n    {\r\n        \"text\": \"jump followed by coming off of the wall\",\r\n        \"start\": 14.519,\r\n        \"duration\": 6.081\r\n    },\r\n    {\r\n        \"text\": \"with your feet and then your hands is\",\r\n        \"start\": 17.96,\r\n        \"duration\": 6.68\r\n    },\r\n    {\r\n        \"text\": \"really going to be a good drill to doing\",\r\n        \"start\": 20.6,\r\n        \"duration\": 6.16\r\n    },\r\n    {\r\n        \"text\": \"the dash VA so let\'s give that a go so\",\r\n        \"start\": 24.64,\r\n        \"duration\": 4.92\r\n    },\r\n    {\r\n        \"text\": \"I\'m going to jump up with two feet and\",\r\n        \"start\": 26.76,\r\n        \"duration\": 3.96\r\n    },\r\n    {\r\n        \"text\": \"then\",\r\n        \"start\": 29.56,\r\n        \"duration\": 3.48\r\n    },\r\n    {\r\n        \"text\": \"up and then coming off with my hands\",\r\n        \"start\": 30.72,\r\n        \"duration\": 4.519\r\n    },\r\n    {\r\n        \"text\": \"behind me landing on the wall and\",\r\n        \"start\": 33.04,\r\n        \"duration\": 5.679\r\n    },\r\n    {\r\n        \"text\": \"pushing away as my feet land so let\'s go\",\r\n        \"start\": 35.239,\r\n        \"duration\": 4.32\r\n    },\r\n    {\r\n        \"text\": \"go\",\r\n        \"start\": 38.719,\r\n        \"duration\": 4.401\r\n    },\r\n    {\r\n        \"text\": \"again up and push away next my hands are\",\r\n        \"start\": 39.559,\r\n        \"duration\": 7.32\r\n    },\r\n    {\r\n        \"text\": \"coming on the edge As I push away um the\",\r\n        \"start\": 43.12,\r\n        \"duration\": 6.439\r\n    },\r\n    {\r\n        \"text\": \"further you can get your feet the better\",\r\n        \"start\": 46.879,\r\n        \"duration\": 4.2\r\n    },\r\n    {\r\n        \"text\": \"uh the more confident you\'re going to\",\r\n        \"start\": 49.559,\r\n        \"duration\": 4.761\r\n    },\r\n    {\r\n        \"text\": \"get with jumping straight over uh but\",\r\n        \"start\": 51.079,\r\n        \"duration\": 6.881\r\n    },\r\n    {\r\n        \"text\": \"yeah you the box jump first obviously is\",\r\n        \"start\": 54.32,\r\n        \"duration\": 4.919\r\n    },\r\n    {\r\n        \"text\": \"going to have to be something that you\",\r\n        \"start\": 57.96,\r\n        \"duration\": 4.36\r\n    },\r\n    {\r\n        \"text\": \"work on start on a lower wall maybe and\",\r\n        \"start\": 59.239,\r\n        \"duration\": 6.761\r\n    },\r\n    {\r\n        \"text\": \"build up but doing the jump two feet and\",\r\n        \"start\": 62.32,\r\n        \"duration\": 6.52\r\n    },\r\n    {\r\n        \"text\": \"then bringing your hands behind you to\",\r\n        \"start\": 66,\r\n        \"duration\": 5.2\r\n    },\r\n    {\r\n        \"text\": \"then push away uh is going to be the\",\r\n        \"start\": 68.84,\r\n        \"duration\": 5.639\r\n    },\r\n    {\r\n        \"text\": \"first step\",\r\n        \"start\": 71.2,\r\n        \"duration\": 3.279\r\n    }\r\n]'),(61926,55514,'_video_transcript_json','field_67221da62655b'),(61927,55514,'video_transcript_srt','1\r\n0